import React from "react";
import "./Getstarted.css";

const Getstarted = () => {
  return (
    <section className="f-section f-section--services" id="services">
      <div className="a-container--full f-section__container">
        <header className="a-gap--s a-stack f-section__header f-section__header--center">
          <small className="f-badge f-badge--accent">Services</small>
          <h2>
            What can we <br /> help you with?
          </h2>
          <p>
            We specialize in crafting websites from idea, through design to
            development and post-deployment follow-up support.
          </p>
        </header>

        <div className="a-gap--s a-stack f-services__groups">
          <article
            className="f-carousel f-carousel--marquee f-scroll--toY0 f-services f-services--bevel f-services--web-design js-carousel--marquee"
            data-speed="0.6"
          >
            <ul
              className="f-carousel__container f-services__container js-carousel__container"
              style={{ transform: "translate3d(0px, 0px, 0px)" }}
            >
              <li className="f-carousel__item f-services__item js-carousel__item">
                <header className="f-services__header">
                  <h3>Web Design</h3>
                </header>
              </li>

              {[
                {
                  title: "Analysis & Research",
                  desc: "Analysis & research to thoroughly analyze your business needs and market trends, creating a strong foundation for your web design project.",
                },
                {
                  title: "User Experience (UX) Audits",
                  desc: "UX audits to identify pain points and opportunities in your current user experience, enhancing usability and engagement.",
                },
                {
                  title: "User Experience (UX) Wireframes",
                  desc: "UX wireframes to map out the structure and functionality of your digital product with clear, user-focused layouts.",
                },
                {
                  title: "User Interface (UI) Prototypes",
                  desc: "UI prototypes to visualize and test the final product through interactive designs before development begins.",
                },
                {
                  title: "Websites",
                  desc: "Websites to elevate your brand and deliver exceptional user experiences through custom web design.",
                },
                {
                  title: "Design Systems",
                  desc: "Design systems to ensure consistency and scalability across all your digital platforms.",
                },
                {
                  title: "Landing Pages",
                  desc: "Landing Pages to capture leads and drive specific actions with high-converting and targeted designs.",
                },
                {
                  title: "Product Pages",
                  desc: "Product Pages to showcase your offerings and encourage conversions with optimized and compelling design.",
                },
                {
                  title: "Dashboards",
                  desc: "Dashboards to provide seamless access, analysis, and actionable insights through intuitive interfaces.",
                },
                {
                  title: "Apps",
                  desc: "Apps to meet your business goals and delight your users with user-friendly and tailored designs.",
                },
                {
                  title: "Brand Identities",
                  desc: "Brand identities that resonate with an audience and effectively communicate brand values.",
                },
                {
                  title: "Newsletters",
                  desc: "Newsletters to engage your subscribers and reinforce your brand's voice through visually appealing designs.",
                },
                {
                  title: "Banners",
                  desc: "Banners to grab attention and drive clicks, enhancing your online campaigns with eye-catching visuals.",
                },
                {
                  title: "Icons",
                  desc: "Icons to enhance usability and add personality to your digital products with custom, unique designs.",
                },
              ].map((service, index) => (
                <li
                  key={index}
                  className="f-badge f-badge--pin f-badge--transparent f-badge--xl f-carousel__item f-services__badge f-services__item js-carousel__item"
                >
                  <abbr
                    className="f-tooltip secret"
                    role="tooltip"
                    tabIndex={0}
                    title={service.desc}
                  >
                    {service.title}
                    <span className="f-tooltip__popup">{service.desc}</span>
                  </abbr>
                </li>
              ))}
            </ul>
          </article>
        </div>

        <a
          className="a-button a-button--icon f-btt__button f-button f-button--deboss"
          href="#top"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            aria-hidden="true"
            className="icon"
            fill="none"
            focusable="false"
            height="24"
            role="img"
            viewBox="0 0 24 24"
            width="24"
          >
            <path
              d="M12 9L15.2929 12.2929C15.9229 12.9229 15.4767 14 14.5858 14H9.41421C8.52331 14 8.07714 12.9229 8.70711 12.2929L12 9Z"
              fill="#fff"
            />
          </svg>
          <span className="a-sr-only">Back to Top</span>
        </a>
      </div>
    </section>
  );
};

export default Getstarted;
